// Vertux AI Trainer — Gate: собирает промпт под режим, режет длину входа.
// Модель меняется тут:
const MODEL = 'openai/gpt-4o-mini';

const inp = $input.first().json;
const b = inp.body || {};
const auth = (inp.headers && (inp.headers.authorization || inp.headers.Authorization)) || '';
const cut = (s, n) => String(s || '').slice(0, n);
const mode = String(b.mode || '');
const niche = cut(b.niche, 80), city = cut(b.city, 40), issues = cut(b.issues, 600), script = cut(b.script, 4000);
let messages = null, max_tokens = 500, temperature = 0.4;

if (!auth) return [{ json: { error: 'not_authenticated' } }];

if (mode === 'suffler') {
  const tr = cut(b.transcript, 6000);
  if (tr.length < 10) return [{ json: { error: 'empty_transcript' } }];
  messages = [
    { role: 'system', content: 'Ты — опытный тренер холодных продаж, работаешь live-суфлёром менеджера веб-студии Vertux (делаем сайты и AI-виджеты малому бизнесу). Тебе приходит хвост разговора, распознанный с микрофона: возможны ошибки распознавания и склеенные реплики — догадывайся по смыслу. Дай 2–4 подсказки, что менеджеру сказать ПРЯМО СЕЙЧАС. Каждая подсказка: готовая живая фраза, которую можно произнести дословно, и в скобках коротко зачем она. Если клиент возразил — отработай возражение по-человечески: сначала присоединись, потом уточняющий вопрос или выгода, без давления и без заученных штампов. Скрипт звонка, если он дан, — опора, а не клетка: улучшай его формулировки, говори разговорным языком, конкретика вместо «уникальных предложений» и канцелярита. Не повторяй подсказку, которую уже давал по этому же возражению. Каждая подсказка с новой строки, начинается с «→».' },
    { role: 'user', content: (script ? 'СКРИПТ ЗВОНКА (опора):\n' + script + '\n\n' : '') + (issues ? 'БОЛЯЧКИ САЙТА КЛИЕНТА (зацепки): ' + issues + '\n\n' : '') + 'РАЗГОВОР (последние реплики, менеджер и клиент вперемешку):\n' + tr }
  ];
  max_tokens = 380;
} else if (mode === 'review') {
  const tr = cut(b.transcript, 12000);
  if (tr.length < 40) return [{ json: { error: 'empty_transcript' } }];
  messages = [
    { role: 'system', content: 'Ты — тренер отдела продаж веб-студии Vertux (холодные звонки малому бизнесу: сайты, AI-виджеты). Разбери транскрипт звонка. Отвечай по-русски, строго в формате:\nОЦЕНКА: X/10\nЧТО СРАБОТАЛО:\n- …\nОШИБКИ:\n- …\nСОВЕТЫ НА СЛЕДУЮЩИЙ ЗВОНОК:\n- … (ровно 3 совета)' + (script ? '\nДан скрипт звонка — отдельной строкой отметь, какие ступени пройдены, какие пропущены.\nСКРИПТ:\n' + script : '') },
    { role: 'user', content: 'ТРАНСКРИПТ:\n' + tr }
  ];
  max_tokens = 700;
} else if (mode === 'roleplay') {
  const hist = Array.isArray(b.history) ? b.history.slice(-14) : [];
  const diff = ['лояльный', 'занятой', 'жёсткий'].includes(b.difficulty) ? b.difficulty : 'занятой';
  messages = [{ role: 'system', content: 'Ты играешь КЛИЕНТА в тренажёре холодных звонков. Твоя роль: владелец бизнеса' + (niche ? ' «' + niche + '»' : ' (малый бизнес)') + (city ? ', город ' + city : '') + '. Характер: ' + diff + '.' + (issues ? ' У твоего сайта есть проблемы: ' + issues + '.' : '') + ' Тебе звонит менеджер веб-студии. Отвечай как живой занятой человек: коротко, 1–3 предложения, с типичными возражениями (нет времени, дорого, уже есть сайт, вышлите на почту). Не выходи из роли и не помогай менеджеру. Если менеджер честно и хорошо отрабатывает возражения — постепенно смягчайся, в конце соглашайся посмотреть демку.' }];
  for (const m of hist) messages.push({ role: m.who === 'm' ? 'user' : 'assistant', content: cut(m.text, 1200) });
  max_tokens = 260; temperature = 0.85;
} else if (mode === 'debrief') {
  const hist = Array.isArray(b.history) ? b.history.slice(-30) : [];
  const dialog = hist.filter(m => m.who === 'm' || m.who === 'c').map(m => (m.who === 'm' ? 'МЕНЕДЖЕР: ' : 'КЛИЕНТ: ') + cut(m.text, 1200)).join('\n');
  if (dialog.length < 20) return [{ json: { error: 'empty_history' } }];
  messages = [
    { role: 'system', content: 'Ты — тренер отдела продаж. Ниже тренировочный холодный звонок: менеджер тренировался на ИИ-клиенте. Разбери работу МЕНЕДЖЕРА по-русски, строго в формате:\nОЦЕНКА: X/10\nЧТО СРАБОТАЛО:\n- …\nОШИБКИ:\n- …\nСОВЕТЫ:\n- … (ровно 3 совета). Коротко и конкретно.' },
    { role: 'user', content: dialog }
  ];
  max_tokens = 600;
} else {
  return [{ json: { error: 'unknown_mode' } }];
}

return [{ json: { ok: true, auth: auth, payload: { model: MODEL, messages: messages, max_tokens: max_tokens, temperature: temperature } } }];

const c = $input.first().json;
const t = (c.choices && c.choices[0] && c.choices[0].message && c.choices[0].message.content) || '';
if (!t) return [{ json: { error: 'llm_empty' } }];
return [{ json: { text: t } }];
